Aquí se presenta un ejemplo de código para un bot de Discord utilizando Discord.js v14 que implementa un comando de ban:

```javascript
// Importar dependencias
const { Client, Intents } = require('discord.js');

const client = new Client({
  intents: [Intents.FLAGS.GUILDS],
});

// Definir eventos de bot
client.on('ready', () => console.log(`Bot listo: ${client.user.tag}`));
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'ban') {
    // Comprobar si el usuario tiene permisos
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return await interaction.reply({ content: 'No tienes permisos para banear miembros!', ephemeral: true });
    }

    const targetMember = interaction.guild.members.cache.get(interaction.options.getMember('usuario').id);

    if (!targetMember) {
      return await interaction.reply({ content: 'No se encontró a ese miembro!', ephemeral: true });
    }

    try {
      await targetMember.ban({ days: 7, reason: `Comando de ban ejecutado por ${interaction.user.tag}` });
      await interaction.reply({ content: `Miembro banido: ${targetMember.user.tag}`, ephemeral: false });
    } catch (error) {
      console.error(error);
      await interaction.reply({ content: 'Falló al banear al miembro!', ephemeral: true });
    }
  }
});

// Iniciar bot
client.login(process.env.TOKEN);
```

Este script asume que ya has configurado tu proyecto de Node.js con variables de entorno para tu token de bot de Discord.

Para usar este bot de Discord, sigue estos pasos:

1. Crea una aplicación en el portal de desarrolladores de Discord y genera un token de bot.
2. Copia y pega tu token de bot en la variable de entorno `TOKEN`.
