Aquí tienes un ejemplo de una función JavaScript que verifica si un número dado es primo y lo imprime si es así:

```javascript
function esPrimo(num) {
  if (num <= 1) return false; // 1 y menores no son primos
  for (let I = 2; I <= Math.sqrt(num); i++) { // solo necesitamos revisar hasta la raíz cuadrada de num
    if (num % I === 0) return false; // num es divisible por algún número entre 2 y Math.sqrt(num), por lo tanto no es primo
  }
  return true;
}

function encontrarPrimos(arr) {
  for (let I = 0; I < arr.length; i++) {
    if (esPrimo(arr[i])) console.log(arr[i]); // si el elemento actual es primo, lo imprime
  }
}

const miArray = [2, 4, 6, 8, 10];
encontrarPrimos(miArray);
```

